//! Which block kernel each core's C driver uses, read from the `#if`
//! chain at the top of `kernel/x86_64/<p>scal.c`. Generated by
//! `tools/blas_asm/uk.zig`; re-derive it rather than editing it.

const uk = @import("../../../uk_block.zig");

pub const Entry = uk.Entry;

pub const entries = [_]Entry{
    .{ .slot = .sscal_k, .cores = &.{
        "haswell",
        "zen",
    }, .mask = 0, .block = .assembly, .kernel = "sscal_kernel_16", .module = @import("sscal_haswell.zig") },
    .{ .slot = .sscal_k, .cores = &.{
        "cooperlake",
        "sapphirerapids",
        "skylakex",
    }, .mask = 0, .block = .vector, .kernel = "", .module = void },
    .{ .slot = .dscal_k, .cores = &.{
        "bulldozer",
        "excavator",
        "piledriver",
        "steamroller",
    }, .mask = 0, .block = .assembly, .kernel = "dscal_kernel_8", .module = @import("dscal_bulldozer.zig"), .own = @import("dscal.zig") },
    .{ .slot = .dscal_k, .cores = &.{
        "sandybridge",
    }, .mask = 0, .block = .assembly, .kernel = "dscal_kernel_8", .module = @import("dscal_sandy.zig"), .own = @import("dscal.zig") },
    .{ .slot = .dscal_k, .cores = &.{
        "haswell",
        "zen",
    }, .mask = 0, .block = .assembly, .kernel = "dscal_kernel_8", .module = @import("dscal_haswell.zig"), .own = @import("dscal.zig") },
    .{ .slot = .dscal_k, .cores = &.{
        "cooperlake",
        "sapphirerapids",
        "skylakex",
    }, .mask = 0, .block = .vector, .kernel = "", .module = void, .own = @import("dscal.zig") },
};

/// The entry for `slot` on `core`, if its driver is C.
pub fn find(comptime slot: uk.Slot, comptime core: []const u8) ?Entry {
    return uk.find(&entries, slot, core);
}
